// Package schema generates the JSON Schema of policy files from the Go types
// the modules decode them into. The files in schemas/ are generated by
// make code-generate and checked by make code-lint.
package schema

import (
	"encoding/json"
	"fmt"
	"reflect"
	"strings"

	"github.com/Kuzmenko-Pavel/gitlab-repopolicy/internal/module"
)

// Draft is the JSON Schema dialect of the generated files.
const Draft = "https://json-schema.org/draft/2020-12/schema"

// FileName is the name of the schema of a module in schemas/.
func FileName(m module.Module) string { return m.Name() + ".schema.json" }

// ForModule returns the schema document of a module, or ok == false when the
// module publishes none.
func ForModule(m module.Module) (doc []byte, ok bool, err error) {
	p, ok := m.(module.SchemaProvider)
	if !ok {
		return nil, false, nil
	}
	doc, err = Document(m.File(), p.SchemaType())
	return doc, true, err
}

// Document renders the schema of v as indented JSON with a trailing newline.
// Struct fields use their yaml names, the tag `schema:"required"` and a
// description from the tag `desc`; every object rejects unknown keys, like
// the strict decoder.
func Document(title string, v any) ([]byte, error) {
	root, err := typeSchema(reflect.TypeOf(v), map[reflect.Type]bool{})
	if err != nil {
		return nil, err
	}
	root["$schema"] = Draft
	root["title"] = title
	data, err := json.MarshalIndent(root, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(data, '\n'), nil
}

var schemaer = reflect.TypeFor[module.JSONSchemaer]()

func typeSchema(t reflect.Type, seen map[reflect.Type]bool) (map[string]any, error) {
	if t == nil {
		return map[string]any{}, nil
	}
	if t.Implements(schemaer) {
		s, ok := reflect.Zero(t).Interface().(module.JSONSchemaer)
		if !ok {
			return nil, fmt.Errorf("schema: %s has a pointer receiver for JSONSchema", t)
		}
		return s.JSONSchema(), nil
	}
	switch t.Kind() {
	case reflect.Pointer:
		return typeSchema(t.Elem(), seen)
	case reflect.String:
		return map[string]any{"type": "string"}, nil
	case reflect.Bool:
		return map[string]any{"type": "boolean"}, nil
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return map[string]any{"type": "integer"}, nil
	case reflect.Float32, reflect.Float64:
		return map[string]any{"type": "number"}, nil
	case reflect.Interface:
		return map[string]any{}, nil
	case reflect.Slice, reflect.Array:
		items, err := typeSchema(t.Elem(), seen)
		if err != nil {
			return nil, err
		}
		return map[string]any{"type": "array", "items": items}, nil
	case reflect.Map:
		if t.Key().Kind() != reflect.String {
			return nil, fmt.Errorf("schema: map key of %s is not a string", t)
		}
		values, err := typeSchema(t.Elem(), seen)
		if err != nil {
			return nil, err
		}
		return map[string]any{"type": "object", "additionalProperties": values}, nil
	case reflect.Struct:
		return structSchema(t, seen)
	default:
		return nil, fmt.Errorf("schema: unsupported type %s", t)
	}
}

func structSchema(t reflect.Type, seen map[reflect.Type]bool) (map[string]any, error) {
	if seen[t] {
		return nil, fmt.Errorf("schema: recursive type %s", t)
	}
	seen[t] = true
	defer delete(seen, t)
	props := map[string]any{}
	var required []string
	for i := range t.NumField() {
		f := t.Field(i)
		if !f.IsExported() {
			continue
		}
		name, _, _ := strings.Cut(f.Tag.Get("yaml"), ",")
		if name == "-" {
			continue
		}
		if name == "" {
			return nil, fmt.Errorf("schema: field %s.%s has no yaml name", t, f.Name)
		}
		s, err := typeSchema(f.Type, seen)
		if err != nil {
			return nil, err
		}
		if d := f.Tag.Get("desc"); d != "" {
			s["description"] = d
		}
		props[name] = s
		if f.Tag.Get("schema") == "required" {
			required = append(required, name)
		}
	}
	out := map[string]any{"type": "object", "properties": props, "additionalProperties": false}
	if len(required) > 0 {
		out["required"] = required
	}
	return out, nil
}
